name,mode,ds,kk,gen=sys.argv[1:];kk=int(kk);P=ROOT/('enemy-'+name+'-'+mode+'-r30');native=['south','south-east','east','north-east','north','north-west','west','south-west'];i=native.index(ds);G=Image.open(P/('generated-'+('A' if i<4 else 'B')+'.png')).convert('RGBA');old=G.crop((round(kk*G.width/4),round(i%4*G.height/4),round((kk+1)*G.width/4),round((i%4+1)*G.height/4)));g=Image.open(gen).convert('RGBA');g.save(P/(ds+'-key'+str(kk)+'-repair-original.png'));ob=box(old,128);nb=box(g,128);sc=(ob[3]-ob[1])/(nb[3]-nb[1]);q=g.crop(nb).resize((round((nb[2]-nb[0])*sc),round((nb[3]-nb[1])*sc)),Image.Resampling.BOX);c=Image.new('RGBA',old.size);xy=(round((ob[0]+ob[2]-q.width)/2),ob[3]-q.height);c.paste(q,xy);f=ds+'-key'+str(kk)+'-raw-repair.png';c.save(P/f);ov=json.loads((P/'raw-key-overrides.json').read_text()) if (P/'raw-key-overrides.json').exists() else {};ov.setdefault(ds,{})[str(kk)]={'file':f,'generationOriginal':ds+'-key'+str(kk)+'-repair-original.png','uniformProviderScale':sc,'oldBox':ob,'generatedBox':nb,'translation':xy,'otherKeysUntouched':True};(P/'raw-key-overrides.json').write_text(json.dumps(ov,indent=2));print(ov[ds][str(kk)])
